                rr, cc = r+k, c-k
                if rr < sep:
                    out[rr][cc] = 4
        elif sep is not None and r > sep:
            for k in range(1, min(h-r, w-c)):
                rr, cc = r+k, c+k
                if rr < h and cc < w:
                    out[rr][cc] = 4
    return out
