 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next((r for r, row in enumerate(grid) if row.count(2) == w), None)
    out = [[0] * w for _ in range(h)]
    if sep is not None:
        out[sep] = grid[sep][:]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 4:
                continue
            if sep is not None and r < sep:
                # Upper-panel markers advance down; two rows above the separator, they
                # form the V pattern observed in the first demonstration.
                if r + 1 < sep:
                    out[r + 1][c] = 4
                if r == sep - 2:
                    apex = r + 1
                    for d in range(1, apex + 1):
                        rr = apex - d
                        for cc in (c - d, c + d):
                            if 0 <= rr < sep and 0 <= cc < w:
                                out[rr][cc] = 4
            elif sep is not None and r > sep:
                # Preserve lower-panel markers in place.
                out[r][c] = 4
    return out
